// Ready-made full outfit sets sold as single fictional-coin bundles.
(() => {
  const bundles=[
    {id:'ninja',name:'Shadow Ninja Set',price:1200,colors:['#171923','#37474f'],boy:'Ninja Suit',girl:'Magic Academy',items:{pants:'Ninja Pants',shoes:'Shadow Shoes',mask:'Ninja Mask',gloves:'Ninja Gloves',belt:'Ninja Belt',emblem:'Moon Emblem',cape:'Shadow Cape',weapon:'Ninja Staff',aura:'Shadow Aura'}},
    {id:'knight',name:'Moon Knight Set',price:1450,colors:['#90a4ae','#455a64'],boy:'Knight Armor',girl:'Moon Knight Armor',items:{pants:'Knight Pants',shoes:'Knight Boots',mask:'Knight Mask',gloves:'Power Gloves',belt:'Champion Belt',emblem:'Shield Emblem',cape:'Royal Cape',weapon:'Knight Sword'}},
    {id:'space',name:'Galaxy Space Set',price:1600,colors:['#eceff1','#5c6bc0'],boy:'Space Suit',girl:'Galaxy Explorer',items:{pants:'Space Pants',shoes:'Rocket Shoes',mask:'Space Mask',gloves:'Space Gloves',belt:'Space Belt',emblem:'Rocket Emblem',cape:'Galaxy Cape',backpack:'Jet Pack',aura:'Galaxy Aura'}},
    {id:'dragon',name:'Dragon Rider Set',price:1750,colors:['#2e7d32','#ffb300'],boy:'Dragon Armor',girl:'Dragon Rider',items:{pants:'Dragon Pants',shoes:'Knight Boots',mask:'Dragon Mask',gloves:'Dragon Gloves',belt:'Dragon Belt',emblem:'Dragon Emblem',cape:'Dragon Cape',wings:'Dragon Wings',weapon:'Dragon Sword'}},
    {id:'wizard',name:'Grand Wizard Set',price:1500,colors:['#512da8','#ffd54f'],boy:'Wizard Robe',girl:'Magic Academy',items:{pants:'Royal Pants',shoes:'Royal Shoes',hat:'Wizard Hat',gloves:'Royal Gloves',belt:'Magic Belt',emblem:'Star Emblem',cape:'Galaxy Cape',weapon:'Magic Wand',aura:'Magic Aura'}},
    {id:'hero',name:'Superhero Set',price:1350,colors:['#1976d2','#e53935'],boy:'Hero Suit',girl:'Super Girl Suit',items:{pants:'Sport Shorts',shoes:'Red Sneakers',mask:'Hero Mask',gloves:'Power Gloves',belt:'Utility Belt',emblem:'Lightning Emblem',cape:'Hero Cape',weapon:'Hero Shield',aura:'Lightning Aura'}},
    {id:'explorer',name:'Forest Explorer Set',price:1100,colors:['#43a047','#795548'],boy:'Explorer Shirt',girl:'Forest Ranger',items:{pants:'Explorer Pants',shoes:'Green Runners',gloves:'Nature Gloves',belt:'Adventure Belt',emblem:'Star Emblem',cape:'Forest Cape',weapon:'Explorer Compass',backpack:'Explorer Pack',aura:'Nature Aura'}},
    {id:'royal',name:'Crystal Royal Set',price:1850,colors:['#7e57c2','#80deea'],boy:'Galaxy Jacket',girl:'Crystal Princess',items:{pants:'Royal Pants',shoes:'Royal Shoes',hat:'Royal Crown',gloves:'Royal Gloves',belt:'Royal Belt',emblem:'Gem Emblem',cape:'Royal Cape',necklace:'Crystal Necklace',aura:'Magic Aura'}},
    {id:'phoenix',name:'Phoenix Fire Set',price:1900,colors:['#f4511e','#ffca28'],boy:'Hero Suit',girl:'Phoenix Guardian',items:{pants:'Sport Shorts',shoes:'Golden Shoes',gloves:'Fire Gloves',belt:'Golden Belt',emblem:'Fire Emblem',cape:'Fire Cape',wings:'Fire Wings',weapon:'Phoenix Scepter',necklace:'Phoenix Pendant',aura:'Phoenix Aura'}},
    {id:'galaxy',name:'Ultimate Galaxy Set',price:2200,colors:['#311b92','#e040fb'],boy:'Galaxy Jacket',girl:'Galaxy Explorer',items:{pants:'Royal Pants',shoes:'Royal Shoes',mask:'Robot Mask',gloves:'Space Gloves',belt:'Space Belt',emblem:'Gem Emblem',cape:'Galaxy Cape',wings:'Galaxy Wings',weapon:'Crystal Staff',backpack:'Galaxy Pack',necklace:'Galaxy Necklace',aura:'Galaxy Aura'}}
  ];
  const bundleName=bundle=>`Full Set: ${bundle.name}`;
  const costume=bundle=>Player.data.outfit?.body==='Girl Hero'?bundle.girl:bundle.boy;
  const unlock=bundle=>{const names=[bundleName(bundle),bundle.boy,bundle.girl,...Object.values(bundle.items)];names.forEach(name=>{if(name&&!Player.data.inventory.includes(name))Player.data.inventory.push(name)})};
  const equip=bundle=>{Player.data.outfit||={};['costume','pants','shoes','mask','hat','glasses','gloves','emblem','necklace','belt','cape','wings','weapon','backpack','aura'].forEach(slot=>Player.data.outfit[slot]='');Player.data.outfit.costume=costume(bundle);Object.entries(bundle.items).forEach(([slot,item])=>Player.data.outfit[slot]=item);Wardrobe.heroAnimation='celebrate';Player.save();App.render()};
  window.OutfitBundles={
    buy(id){const bundle=bundles.find(item=>item.id===id);if(!bundle)return;if(Player.data.inventory.includes(bundleName(bundle)))return equip(bundle);if(Player.data.coins<bundle.price)return Rewards.toast('Earn more coins by learning!');Player.data.coins-=bundle.price;unlock(bundle);equip(bundle);Rewards.toast(`${bundle.name} unlocked and equipped!`)},
    equip(id){const bundle=bundles.find(item=>item.id===id);if(bundle)equip(bundle)},
    render(){return `<section class="bundle-shop"><div class="shop-section-head"><div><p class="eyebrow">One tap equips everything</p><h2>🦸 Complete Outfit Sets</h2><p>Each set includes matching clothes and accessories.</p></div><span>10 ready-made sets</span></div><div class="bundle-grid">${bundles.map(bundle=>{const owned=Player.data.inventory.includes(bundleName(bundle));return `<article class="bundle-card card" style="--bundle-a:${bundle.colors[0]};--bundle-b:${bundle.colors[1]}"><div class="bundle-preview"><i></i><b></b><em></em></div><h3>${bundle.name}</h3><p>${Object.values(bundle.items).slice(0,5).join(' · ')}</p><small>${owned?'✓ Complete set owned':`🪙 ${bundle.price}`}</small><button class="btn ${owned?'green':'gold'}" onclick="OutfitBundles.${owned?'equip':'buy'}('${bundle.id}')">${owned?'Equip Full Set':'Buy Full Set'}</button></article>`}).join('')}</div></section>`}
  };
  const originalShop=App.shop.bind(App);App.shop=function shopWithOutfitSets(){return originalShop()+OutfitBundles.render()};
})();
